#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const frontendRoot = path.join(
  repositoryRoot,
  "custom_components",
  "vless_gateway",
  "frontend",
);
const sources = [
  path.join(frontendRoot, "src", "zoom-controller.js"),
  path.join(frontendRoot, "src", "vless-gateway-panel.js"),
];
const outputPath = path.join(frontendRoot, "vless-gateway-panel.js");
const checkOnly = process.argv.includes("--check");

const chunks = await Promise.all(sources.map((source) => readFile(source, "utf8")));
const output = [
  "// Generated by scripts/build-frontend-bundle.mjs. Do not edit directly.",
  "// VLESS Gateway UI v0.1.0 · autonomous production bundle.",
  ...chunks.map((chunk) => chunk.trimEnd()),
].join("\n\n") + "\n";

if (checkOnly) {
  let current = "";
  try {
    current = await readFile(outputPath, "utf8");
  } catch (_error) {
    process.stderr.write(`Missing generated bundle: ${path.relative(repositoryRoot, outputPath)}\n`);
    process.exitCode = 1;
    process.exit();
  }
  if (current !== output) {
    process.stderr.write("Frontend bundle is stale. Run: node scripts/build-frontend-bundle.mjs\n");
    process.exitCode = 1;
  }
} else {
  await writeFile(outputPath, output, "utf8");
  process.stdout.write(`${path.relative(repositoryRoot, outputPath)}\n`);
}
